B.bJP=new A.a_("Her ayda g\xf6r\xfclen hastal\u0131klar ve \xf6nleme tedbirleri. Aya dokununca hastal\u0131klar, hastal\u0131\u011fa dokununca etken ve tedbirler a\xe7\u0131l\u0131r. Tedbirler genel bilgidir; a\u015f\u0131 program\u0131 ve ila\xe7lar \xe7iftlik veterineri ile teyit edilir.",null,B.bM,null,null,null,null,null,null,null,null)
